  const bulkDiscount = lineBulkDiscount(line);
  assert.equal(Number.isInteger(bulkDiscount), true);
});

test('lineVAT with bulk discount', () => {
  const line = { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 };
  const total = lineTotal(line);
  const bulkDiscount = lineBulkDiscount(line);
  const vatBase = total - bulkDiscount;
  const vat = lineVAT(line);
  assert.equal(vat, Math.max(0, Math.round(vatBase * 0.21)));
});

test('lineVAT with bulk discount and existing discount', () => {
  const line = { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 };
  const total = lineTotal(line);
  const regularDiscount = lineDiscount(line);
  const bulkDiscount = lineBulkDiscount(line);
  const vatBase = total - regularDiscount - bulkDiscount;
  const vat = lineVAT(line);
  assert.equal(vat, Math.max(0, Math.round(vatBase * 0.21)));
});

test('invoiceTotals includes bulk discount in discount field', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedBulkDiscount = Math.round(100000 * 0.025);
  assert.equal(totals.discount, expectedBulkDiscount);
});

test('invoiceTotals with bulk discount and regular discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const total = lineTotal(invoice.lines[0]);
  const regularDiscount = lineDiscount(invoice.lines[0]);
  const bulkDiscount = lineBulkDiscount(invoice.lines[0]);
  assert.equal(totals.discount, regularDiscount + bulkDiscount);
});

test('invoiceTotals with mix of lines with and without bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
      { qty: 5, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const bulkDiscountLine1 = lineBulkDiscount(invoice.lines[0]);
  const bulkDiscountLine2 = lineBulkDiscount(invoice.lines[1]);
  assert.equal(totals.discount, bulkDiscountLine1 + bulkDiscountLine2);
  assert.equal(bulkDiscountLine2, 0);
});

test('invoiceTotals formula with bulk discount: total = subtotal - (regular + bulk) + vat - voucher', () => {
  const invoice = {
    voucher: { code: 'SAVE', amount: 5000 },
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line = invoice.lines[0];
  const lineSubtotal = lineTotal(line);
  const lineRegularDiscount = lineDiscount(line);
  const lineBulk = lineBulkDiscount(line);
  const lineVatAmount = lineVAT(line);
  const expected = lineSubtotal - lineRegularDiscount - lineBulk + lineVatAmount - 5000;
  assert.equal(totals.total, Math.max(0, expected));
});

test('lineBulkDiscount with 100% regular discount', () => {
