18	function calculateDueDate(issueDate, terms) {
19	  if (terms === 'NET14') {
20	    return addDays(issueDate, 14);
21	  } else if (terms === 'NET30') {
22	    return addDays(issueDate, 30);
23	  } else if (terms === 'EOM') {
24	    const date = new Date(issueDate + 'T00:00:00Z');
25	    const year = date.getUTCFullYear();
26	    const month = date.getUTCMonth();
27	    const lastDayOfMonth = new Date(Date.UTC(year, month + 1, 0));
28	    return lastDayOfMonth.toISOString().split('T')[0];
29	  }
30	  return null;
31	}
32	
33	function addDays(dateString, n) {
34	  const date = new Date(dateString + 'T00:00:00Z');
35	  const newDate = new Date(date.getTime() + n * 24 * 60 * 60 * 1000);
36	  return newDate.toISOString().split('T')[0];
37	}
