39	export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
40	  const normalizedCustomerId = normalizeId(customerId);
41	  const customerResult = getCustomer(normalizedCustomerId);
42	  if (!customerResult.ok) return customerResult;
43	
44	  if (!isValidDate(issueDate)) return fail('DATE_INVALID');
45	
46	  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');
47	
48	  if (!['NET14', 'NET30', 'EOM'].includes(terms)) return fail('TERMS_INVALID');
49	
50	  const customer = customerResult.value;
51	  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
52	
53	  const invoiceLines = [];
54	  for (const line of lines) {
55	    if (!isPositiveInteger(line.qty)) return fail('QTY_INVALID');
56	
57	    if (line.discountPercent !== undefined && !isValidDiscount(line.discountPercent)) {
58	      return fail('DISCOUNT_INVALID');
59	    }
60	
61	    const productResult = getProduct(line.sku);
62	    if (!productResult.ok) return productResult;
63	
64	    const product = productResult.value;
65	    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;
66	    invoiceLines.push({
67	      sku: line.sku,
68	      name: product.name,
69	      qty: line.qty,
70	      unitPrice: product.unitPrice,
71	      vatRate: product.vatRate,
72	      discountPercent,
73	    });
74	  }
75	
76	  const dueDate = calculateDueDate(issueDate, terms);
77	
78	  return ok({
79	    customerId: normalizedCustomerId,
80	    issueDate,
81	    status: 'draft',
82	    terms,
83	    dueDate,
84	    lines: invoiceLines,
85	  });
86	}
