88	export function addLine(invoice, { sku, qty, discountPercent }) {
89	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
90	
91	  if (!isPositiveInteger(qty)) return fail('QTY_INVALID');
92	
93	  if (discountPercent !== undefined && !isValidDiscount(discountPercent)) {
94	    return fail('DISCOUNT_INVALID');
95	  }
96	
97	  const productResult = getProduct(sku);
98	  if (!productResult.ok) return productResult;
99	
100	  const product = productResult.value;
101	  const newLines = invoice.lines.map((line) => ({ ...line }));
102	
103	  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
104	  if (existingLineIndex >= 0) {
105	    newLines[existingLineIndex].qty += qty;
106	  } else {
107	    newLines.push({
108	      sku,
109	      name: product.name,
110	      qty,
111	      unitPrice: product.unitPrice,
112	      vatRate: product.vatRate,
113	      discountPercent: discountPercent ?? 0,
114	    });
115	  }
116	
117	  return ok({
118	    customerId: invoice.customerId,
119	    issueDate: invoice.issueDate,
120	    status: invoice.status,
121	    lines: newLines,
122	  });
123	}
124	
125	export function removeLine(invoice, sku) {
126	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
127	
128	  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
129	  if (lineIndex < 0) return fail('LINE_NOT_FOUND');
130	
131	  if (invoice.lines.length === 1) return fail('NO_LINES');
132	
133	  const newLines = invoice.lines.filter((line) => line.sku !== sku);
134	
135	  return ok({
136	    customerId: invoice.customerId,
137	    issueDate: invoice.issueDate,
138	    status: invoice.status,
139	    lines: newLines,
140	  });
141	}
142	
143	export function issueInvoice(invoice, existingNumbers) {
144	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
145	
146	  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);
147	
148	  return ok({
149	    number,
150	    customerId: invoice.customerId,
151	    issueDate: invoice.issueDate,
152	    status: 'issued',
153	    lines: invoice.lines.map((line) => ({ ...line })),
154	  });
155	}
156	
157	export function applyVoucher(invoice, { code, amount }) {
158	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
159	
160	  if (invoice.voucher) return fail('VOUCHER_EXISTS');
161	
162	  if (!isPositiveInteger(amount)) return fail('AMOUNT_INVALID');
163	
164	  return ok({
165	    ...invoice,
166	    voucher: { code, amount },
167	  });
168	}
