1	import { roundCents } from './money.js';
2	
3	export function lineTotal(line) {
4	  return roundCents(line.qty * line.unitPrice);
5	}
6	
7	export function lineDiscount(line) {
8	  const total = lineTotal(line);
9	  const discount = roundCents(total * (line.discountPercent ?? 0) / 100);
10	  return Math.max(0, discount);
11	}
12	
13	export function lineBulkDiscount(line) {
14	  if (line.qty < 10) {
15	    return 0;
16	  }
17	  const total = lineTotal(line);
18	  const regularDiscount = lineDiscount(line);
19	  const amountAfterDiscount = Math.max(0, total - regularDiscount);
20	  const bulkDiscount = roundCents(amountAfterDiscount * 0.025);
21	  return Math.max(0, bulkDiscount);
22	}
23	
24	export function lineVAT(line) {
25	  const total = lineTotal(line);
26	  const regularDiscount = lineDiscount(line);
27	  const bulkDiscount = lineBulkDiscount(line);
28	  const amount = Math.max(0, total - regularDiscount - bulkDiscount);
29	  const vat = roundCents(amount * (line.vatRate ?? 0) / 100);
30	  return Math.max(0, vat);
31	}
32	
33	export function invoiceTotals(invoice) {
34	  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
35	  const regularDiscount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
36	  const bulkDiscount = invoice.lines.reduce((sum, line) => sum + lineBulkDiscount(line), 0);
37	  const discount = regularDiscount + bulkDiscount;
38	  const vat = invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0);
39	  const voucher = Math.max(0, invoice.voucher?.amount ?? 0);
40	  const total = Math.max(0, subtotal - discount + vat - voucher);
41	  return {
42	    subtotal,
43	    discount,
44	    vat,
45	    voucher,
46	    total,
47	  };
48	}
