1	import { ok, fail } from './result.js';
2	
3	export const RATES = { EUR: 1, USD: 1.085, GBP: 0.8425 };
4	
5	/**
6	 * Round a (possibly fractional) number of cents to a whole cent, half to even (banker's rounding):
7	 * 124.5 -> 124, 125.5 -> 126, 2.4 -> 2, -0.5 -> 0.
8	 * @param {number} x
9	 * @returns {number}
10	 */
11	export function roundCents(x) {
12	  const r = Math.round(x * 1e6) / 1e6; // drop binary noise such as 124.49999999999999
13	  const floor = Math.floor(r);
14	  const diff = r - floor;
15	  if (diff > 0.5) return floor + 1;
16	  if (diff < 0.5) return floor === 0 ? 0 : floor;
17	  return floor % 2 === 0 ? floor : floor + 1;
18	}
19	
20	/**
21	 * Format cents as euros for people: 123456 -> "€1,234.56", -5 -> "-€0.05".
22	 * @param {number} cents
23	 * @returns {string}
24	 */
25	export function formatEuros(cents) {
26	  const sign = cents < 0 ? '-' : '';
27	  const abs = Math.abs(cents);
28	  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
29	  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
30	}
31	
32	/**
33	 * Convert EUR cents to another currency's cents.
34	 * @param {number} cents
35	 * @param {string} currency
36	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
37	 */
38	export function convert(cents, currency) {
39	  if (!(currency in RATES)) {
40	    return fail('UNKNOWN_CURRENCY');
41	  }
42	  const converted = roundCents(cents * RATES[currency]);
43	  return ok(converted);
44	}
45	
46	/**
47	 * Format cents in a given currency for people: 123456 EUR -> "€1,234.56", 123456 USD -> "$1,234.56".
48	 * @param {number} cents
49	 * @param {string} currency
50	 * @returns {string}
51	 */
52	export function formatMoney(cents, currency) {
53	  if (!(currency in RATES)) {
54	    return '';
55	  }
56	  const sign = cents < 0 ? '-' : '';
57	  const abs = Math.abs(cents);
58	  const units = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
59	  const symbol = currency === 'USD' ? '$' : currency === 'GBP' ? '£' : '€';
60	  return `${sign}${symbol}${units}.${String(abs % 100).padStart(2, '0')}`;
61	}
62	
63	/**
64	 * Parse a euro amount typed by a person ("12", "12.5", "1,234.56") into cents.
65	 * @param {string} text
66	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
67	 */
68	export function parseEuros(text) {
69	  const m = /^(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
70	  if (!m) return fail('AMOUNT_INVALID');
71	  const euros = Number(m[1].replace(/,/g, ''));
72	  const cents = Number((m[2] ?? '').padEnd(2, '0'));
73	  return ok(euros * 100 + cents);
74	}
