1	import { ok, fail } from './result.js';
2	import { invoiceTotals } from './invoices.js';
3	import { isValidDate } from './dates.js';
4	
5	function isPositiveInteger(val) {
6	  return Number.isInteger(val) && val > 0;
7	}
8	
9	export function nextCreditNoteNumber(existingNumbers, issueDate) {
10	  const year = issueDate.split('-')[0];
11	  const prefix = `CN-${year}-`;
12	
13	  const thisYearNumbers = existingNumbers
14	    .filter((num) => num.startsWith(prefix))
15	    .map((num) => {
16	      const counter = num.slice(prefix.length);
17	      return parseInt(counter, 10);
18	    })
19	    .filter((num) => !isNaN(num));
20	
21	  const maxCounter = thisYearNumbers.length > 0 ? Math.max(...thisYearNumbers) : 0;
22	  const nextCounter = maxCounter + 1;
23	
24	  return `${prefix}${String(nextCounter).padStart(4, '0')}`;
25	}
26	
27	export function createCreditNote(invoice, { amount, reason, date }, existingNumbers) {
28	  if (invoice.status !== 'issued' && invoice.status !== 'partially_paid' && invoice.status !== 'paid') {
29	    return fail('NOT_ISSUED');
30	  }
31	
32	  if (!isPositiveInteger(amount)) {
33	    return fail('AMOUNT_INVALID');
34	  }
35	
36	  if (!isValidDate(date)) {
37	    return fail('DATE_INVALID');
38	  }
39	
40	  const invoiceTotal = invoiceTotals(invoice).total;
41	  if (amount > invoiceTotal) {
42	    return fail('CREDIT_TOO_HIGH');
43	  }
44	
45	  const number = nextCreditNoteNumber(existingNumbers, date);
46	
47	  return ok({
48	    number,
49	    invoiceNumber: invoice.number,
50	    customerId: invoice.customerId,
51	    amount,
52	    reason,
53	    date,
54	  });
55	}
