        qty: 1,
        unitPrice: 60000,
        vatRate: 0,
        discountPercent: 0,
      },
    ],
  };

  const totals = invoiceTotals(invoice);

  // Line 1: qty=10, lineTotal=95000, bulkDiscount=2.5% of 95000 = 2375
  // Line 2: qty=100, lineTotal=3700, bulkDiscount=2.5% of 3700 = 93 (rounded)
  // Line 3: qty=1, lineTotal=60000, bulkDiscount=0 (qty < 10)
  const line1VAT = Math.round((95000 - 2375) * 21 / 100);
  const line2VAT = Math.round((3700 - 93) * 9 / 100);
  const line3VAT = 0;
  const totalDiscount = 2375 + 93;

  assert.equal(totals.vat, line1VAT + line2VAT + line3VAT);
  assert.equal(totals.total, 95000 + 3700 + 60000 - totalDiscount + (line1VAT + line2VAT + line3VAT));
});

