  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 2 },
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'LOGO-PACK', qty: 1 },
