  const totalDiscount = 2375 + 93;

  assert.equal(totals.vat, line1VAT + line2VAT + line3VAT);
  assert.equal(totals.total, 95000 + 3700 + 60000 - totalDiscount + (line1VAT + line2VAT + line3VAT));
});

