test('invoiceTotals includes discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 10,
      },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000);
  // Regular discount: 10% of 95000 = 9500
  // Bulk discount (qty >= 10): 2.5% of (95000 - 9500) = 2.5% of 85500 = 2137.5 -> 2138 (banker's rounding)
  const expectedDiscount = 9500 + 2138;
  assert.equal(totals.discount, expectedDiscount);
  const expectedVAT = Math.round((95000 - expectedDiscount) * 21 / 100);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, 95000 - expectedDiscount + expectedVAT);
});

test('invoiceTotals calculates discount across multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 10,
      },
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 5,
        unitPrice: 8500,
        vatRate: 21,
        discountPercent: 20,
      },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000 + 42500);
  // Line 1: qty=10, regular discount = 9500, bulk discount = 2.5% of 85500 = 2138
  // Line 2: qty=5, regular discount = 8500, bulk discount = 0 (qty < 10)
  const expectedDiscount = 9500 + 2138 + 8500 + 0;
  assert.equal(totals.discount, expectedDiscount);
  const line1Amount = 95000 - 9500 - 2138;
  const line2Amount = 42500 - 8500 - 0;
  const expectedVAT = Math.round(line1Amount * 21 / 100) + Math.round(line2Amount * 21 / 100);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, 137500 - expectedDiscount + expectedVAT);
});

