test('invoiceTotals includes voucher', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
    voucher: { code: 'SUMMER20', amount: 5000 },
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000);
  // Regular discount: 0
  // Bulk discount (qty >= 10): 2.5% of 95000 = 2375
  const expectedDiscount = 2375;
  assert.equal(totals.discount, expectedDiscount);
  const expectedVAT = Math.round((95000 - expectedDiscount) * 21 / 100);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, 95000 - expectedDiscount + expectedVAT - 5000);
});

test('invoiceTotals with voucher, discount, and VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 100,
        unitPrice: 10000,
        vatRate: 21,
        discountPercent: 10,
      },
    ],
    voucher: { code: 'SUMMER20', amount: 50000 },
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 1000000);
  // Regular discount: 10% of 1000000 = 100000
  // Bulk discount (qty >= 10): 2.5% of (1000000 - 100000) = 2.5% of 900000 = 22500
  const expectedDiscount = 100000 + 22500;
  assert.equal(totals.discount, expectedDiscount);
  const expectedVAT = Math.round((1000000 - expectedDiscount) * 21 / 100);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.voucher, 50000);
  assert.equal(totals.total, 1000000 - expectedDiscount + expectedVAT - 50000);
});

