test('invoiceTotals calculates VAT across multiple lines with different rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
      {
        sku: 'PRINT-A4',
        name: 'Printed flyer A4 (each)',
        qty: 100,
        unitPrice: 37,
        vatRate: 9,
        discountPercent: 0,
      },
      {
        sku: 'WORKSHOP-DAY',
        name: 'Brand workshop (day, VAT exempt)',
        qty: 1,
        unitPrice: 60000,
        vatRate: 0,
        discountPercent: 0,
      },
    ],
  };

  const totals = invoiceTotals(invoice);

  // Line 1: qty=10, lineTotal=95000, bulkDiscount=2.5% of 95000 = 2375
  // Line 2: qty=100, lineTotal=3700, bulkDiscount=2.5% of 3700 = 93 (rounded)
  // Line 3: qty=1, lineTotal=60000, bulkDiscount=0 (qty < 10)
  const line1VAT = Math.round((95000 - 2375) * 21 / 100);
  const line2VAT = Math.round((3700 - 93) * 9 / 100);
  const line3VAT = 0;
  const totalDiscount = 2375 + 93;

  assert.equal(totals.vat, line1VAT + line2VAT + line3VAT);
  assert.equal(totals.total, 95000 + 3700 + 60000 - totalDiscount + (line1VAT + line2VAT + line3VAT));
});

