  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 125000);
  const line1BulkDiscount = Math.round(100000 * 0.025);
  assert.equal(totals.discount, line1BulkDiscount);
  const line1VatBase = 100000 - line1BulkDiscount;
  const line2VatBase = 25000;
  const expectedVat = Math.round(line1VatBase * 0.21) + Math.round(line2VatBase * 0.09);
  assert.equal(totals.vat, expectedVat);
});

test('invoiceTotals with zero-VAT line', () => {
