});

test('lineDiscount with 50% discount', () => {
  const line = { qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 50 };
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  assert.equal(discount, total / 2);
});

test('lineVAT with 50% discount', () => {
  const line = { qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 50 };
  const total = lineTotal(line);
  const regularDiscount = lineDiscount(line);
  const bulkDiscount = lineBulkDiscount(line);
  const vatBase = total - regularDiscount - bulkDiscount;
  const vat = lineVAT(line);
  assert.equal(vat, Math.max(0, Math.round(vatBase * 0.21)));
});

test('invoiceTotals with discount on all lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 },
      { qty: 5, unitPrice: 10000, vatRate: 21, discountPercent: 10 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1RegularDiscount = 10000;
  const line1BulkDiscount = Math.round((100000 - 10000) * 0.025);
  const line2RegularDiscount = 5000;
  const line2BulkDiscount = 0;
  assert.equal(totals.discount, line1RegularDiscount + line1BulkDiscount + line2RegularDiscount + line2BulkDiscount);
});

test('invoiceTotals voucher with zero amount', () => {
  const invoice = {
    voucher: { code: 'ZERO', amount: 0 },
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals with three VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
      { qty: 5, unitPrice: 10000, vatRate: 9, discountPercent: 0 },
      { qty: 2, unitPrice: 10000, vatRate: 0, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 170000);
  const line1BulkDiscount = Math.round(100000 * 0.025);
  assert.equal(totals.discount, line1BulkDiscount);
  const line1VatBase = 100000 - line1BulkDiscount;
  const line2VatBase = 50000;
  assert.equal(totals.vat, Math.round(line1VatBase * 0.21) + Math.round(line2VatBase * 0.09));
});

test('lineBulkDiscount with qty < 10 returns 0', () => {
  const line = { qty: 9, unitPrice: 10000, vatRate: 21, discountPercent: 0 };
  assert.equal(lineBulkDiscount(line), 0);
});

test('lineBulkDiscount with qty = 10 returns 2.5%', () => {
  const line = { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 };
  const total = lineTotal(line);
  const bulkDiscount = lineBulkDiscount(line);
  assert.equal(bulkDiscount, Math.round(total * 0.025));
});

test('lineBulkDiscount with qty > 10 returns 2.5%', () => {
  const line = { qty: 20, unitPrice: 10000, vatRate: 21, discountPercent: 0 };
  const total = lineTotal(line);
  const bulkDiscount = lineBulkDiscount(line);
  assert.equal(bulkDiscount, Math.round(total * 0.025));
});

test('lineBulkDiscount with existing discount applies to post-discount amount', () => {
  const line = { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 };
  const total = lineTotal(line);
  const regularDiscount = lineDiscount(line);
  const amountAfterDiscount = total - regularDiscount;
  const bulkDiscount = lineBulkDiscount(line);
  assert.equal(bulkDiscount, Math.round(amountAfterDiscount * 0.025));
});

test('lineBulkDiscount is clamped at 0', () => {
  const line = { qty: 10, unitPrice: 0, vatRate: 21, discountPercent: 0 };
  assert.equal(lineBulkDiscount(line), 0);
});

test('lineBulkDiscount applies rounding', () => {
  const line = { qty: 10, unitPrice: 10001, vatRate: 21, discountPercent: 0 };
  const bulkDiscount = lineBulkDiscount(line);
  assert.equal(Number.isInteger(bulkDiscount), true);
});

test('lineVAT with bulk discount', () => {
  const line = { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 };
  const total = lineTotal(line);
  const bulkDiscount = lineBulkDiscount(line);
  const vatBase = total - bulkDiscount;
  const vat = lineVAT(line);
  assert.equal(vat, Math.max(0, Math.round(vatBase * 0.21)));
});

test('lineVAT with bulk discount and existing discount', () => {
  const line = { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 };
  const total = lineTotal(line);
  const regularDiscount = lineDiscount(line);
  const bulkDiscount = lineBulkDiscount(line);
  const vatBase = total - regularDiscount - bulkDiscount;
  const vat = lineVAT(line);
  assert.equal(vat, Math.max(0, Math.round(vatBase * 0.21)));
});

test('invoiceTotals includes bulk discount in discount field', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedBulkDiscount = Math.round(100000 * 0.025);
  assert.equal(totals.discount, expectedBulkDiscount);
});

test('invoiceTotals with bulk discount and regular discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const total = lineTotal(invoice.lines[0]);
  const regularDiscount = lineDiscount(invoice.lines[0]);
  const bulkDiscount = lineBulkDiscount(invoice.lines[0]);
  assert.equal(totals.discount, regularDiscount + bulkDiscount);
});

test('invoiceTotals with mix of lines with and without bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
      { qty: 5, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const bulkDiscountLine1 = lineBulkDiscount(invoice.lines[0]);
  const bulkDiscountLine2 = lineBulkDiscount(invoice.lines[1]);
  assert.equal(totals.discount, bulkDiscountLine1 + bulkDiscountLine2);
  assert.equal(bulkDiscountLine2, 0);
});

test('invoiceTotals formula with bulk discount: total = subtotal - (regular + bulk) + vat - voucher', () => {
  const invoice = {
    voucher: { code: 'SAVE', amount: 5000 },
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line = invoice.lines[0];
  const lineSubtotal = lineTotal(line);
  const lineRegularDiscount = lineDiscount(line);
  const lineBulk = lineBulkDiscount(line);
  const lineVatAmount = lineVAT(line);
  const expected = lineSubtotal - lineRegularDiscount - lineBulk + lineVatAmount - 5000;
  assert.equal(totals.total, Math.max(0, expected));
});

test('lineBulkDiscount with 100% regular discount', () => {
  const line = { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 100 };
  const bulkDiscount = lineBulkDiscount(line);
  assert.equal(bulkDiscount, 0);
});

test('lineBulkDiscount with 50% regular discount', () => {
  const line = { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 50 };
  const total = lineTotal(line);
  const regularDiscount = lineDiscount(line);
  const amountAfterDiscount = total - regularDiscount;
  const expectedBulk = Math.round(amountAfterDiscount * 0.025);
  assert.equal(lineBulkDiscount(line), expectedBulk);
});

test('invoiceTotals with multiple lines bulk discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
      { qty: 10, unitPrice: 10000, vatRate: 9, discountPercent: 0 },
      { qty: 10, unitPrice: 10000, vatRate: 0, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const bulkDiscounts = invoice.lines.map((line) => lineBulkDiscount(line));
  const totalBulkDiscount = bulkDiscounts.reduce((a, b) => a + b, 0);
  assert.equal(totals.discount, totalBulkDiscount);
});

test('lineVAT is zero when line is fully discounted with bulk discount', () => {
  const line = { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 };
  const total = lineTotal(line);
  const bulkDiscount = lineBulkDiscount(line);
  // If bulk discount equals total, VAT should be 0
  // But 2.5% is much less, so this just tests normal case
  const vat = lineVAT(line);
  assert(vat > 0);
});

test('lineBulkDiscount threshold at exactly 10 items', () => {
  const line9 = { qty: 9, unitPrice: 10000, vatRate: 21, discountPercent: 0 };
  const line10 = { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 };
  assert.equal(lineBulkDiscount(line9), 0);
  assert(lineBulkDiscount(line10) > 0);
});

test('invoiceTotals without bulk discount lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
      { qty: 9, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.discount, 0);
});

