    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals with three VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
      { qty: 5, unitPrice: 10000, vatRate: 9, discountPercent: 0 },
      { qty: 2, unitPrice: 10000, vatRate: 0, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 170000);
  const line1BulkDiscount = Math.round(100000 * 0.025);
  assert.equal(totals.discount, line1BulkDiscount);
  const line1VatBase = 100000 - line1BulkDiscount;
  const line2VatBase = 50000;
  assert.equal(totals.vat, Math.round(line1VatBase * 0.21) + Math.round(line2VatBase * 0.09));
});

test('lineBulkDiscount with qty < 10 returns 0', () => {
  const line = { qty: 9, unitPrice: 10000, vatRate: 21, discountPercent: 0 };
  assert.equal(lineBulkDiscount(line), 0);
});

test('lineBulkDiscount with qty = 10 returns 2.5%', () => {
  const line = { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 };
  const total = lineTotal(line);
  const bulkDiscount = lineBulkDiscount(line);
  assert.equal(bulkDiscount, Math.round(total * 0.025));
});

test('lineBulkDiscount with qty > 10 returns 2.5%', () => {
  const line = { qty: 20, unitPrice: 10000, vatRate: 21, discountPercent: 0 };
  const total = lineTotal(line);
  const bulkDiscount = lineBulkDiscount(line);
  assert.equal(bulkDiscount, Math.round(total * 0.025));
});

test('lineBulkDiscount with existing discount applies to post-discount amount', () => {
  const line = { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 };
  const total = lineTotal(line);
  const regularDiscount = lineDiscount(line);
  const amountAfterDiscount = total - regularDiscount;
  const bulkDiscount = lineBulkDiscount(line);
  assert.equal(bulkDiscount, Math.round(amountAfterDiscount * 0.025));
});

test('lineBulkDiscount is clamped at 0', () => {
  const line = { qty: 10, unitPrice: 0, vatRate: 21, discountPercent: 0 };
  assert.equal(lineBulkDiscount(line), 0);
});

test('lineBulkDiscount applies rounding', () => {
  const line = { qty: 10, unitPrice: 10001, vatRate: 21, discountPercent: 0 };
  const bulkDiscount = lineBulkDiscount(line);
  assert.equal(Number.isInteger(bulkDiscount), true);
});

test('lineVAT with bulk discount', () => {
  const line = { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 0 };
  const total = lineTotal(line);
  const bulkDiscount = lineBulkDiscount(line);
  const vatBase = total - bulkDiscount;
  const vat = lineVAT(line);
  assert.equal(vat, Math.max(0, Math.round(vatBase * 0.21)));
});

test('lineVAT with bulk discount and existing discount', () => {
  const line = { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 };
  const total = lineTotal(line);
  const regularDiscount = lineDiscount(line);
  const bulkDiscount = lineBulkDiscount(line);
  const vatBase = total - regularDiscount - bulkDiscount;
  const vat = lineVAT(line);
  assert.equal(vat, Math.max(0, Math.round(vatBase * 0.21)));
});

