import test from 'node:test';
import assert from 'node:assert/strict';
import { recordPayment, balanceDue } from '../src/payments.js';

test('balanceDue returns the full total for unpaid invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const balance = balanceDue(invoice);
  assert(balance > 0);
});

test('balanceDue returns 0 for fully paid invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'paid',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
    // With bulk discount: total = 95000 - 2375 + 19451 = 112076
    payments: [{ amount: 112076, date: '2026-10-10' }],
  };

  const balance = balanceDue(invoice);
  assert.equal(balance, 0);
});

test('balanceDue accounts for partial payments', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 10000,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
    payments: [{ amount: 50000, date: '2026-10-10' }],
  };

  const balance = balanceDue(invoice);
  assert(balance > 0);
  assert(balance < 121000);
});

